{
  "name": "@danwad/opencode-auto-models",
  "version": "1.1.0",
  "description": "OpenCode plugin: descubre automaticamente los modelos nuevos de tus gateways OpenAI-compatibles y los sincroniza con tu opencode.jsonc. Comandos /sync-models y /prune-models.",
  "type": "module",
  "main": "./dist/auto-models.js",
  "types": "./dist/auto-models.d.ts",
  "files": [
    "dist",
    "src",
    "install.ps1"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "models",
    "openai-compatible",
    "sync"
  ],
  "license": "MIT",
  "author": "Daniel (https://github.com/deathcl)",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/deathcl/opencode-auto-models.git"
  },
  "bugs": {
    "url": "https://github.com/deathcl/opencode-auto-models/issues"
  },
  "homepage": "https://github.com/deathcl/opencode-auto-models#readme",
  "dependencies": {
    "@opencode/plugin": "^2.0.28"
  },
  "devDependencies": {
    "typescript": "^5.9.3"
  }
}
